def average(*scores):
    if not scores:
        return 0
    return sum(scores) / len(scores)

print(average())              # 0
print(average(4, 5))          # 4.5
print(average(4, 5, 3, 6))    # 4.5

marks = [2, 5, 5]
print(average(*marks))        # распаковка списка в аргументы

role = "гость"          # Global

def dashboard():
    role = "админ"      # Local, глобальная не страдает
    def badge():
        return f"бейдж: {role}"   # Enclosing — берёт role из dashboard
    return badge()

print(dashboard())      # бейдж: админ
print(role)             # гость
